-- Generated by scripts/build-x-oauth-migration.mjs. Installs only; never executes a reset.
BEGIN;

-- Source: 01_create_reset_registry.sql
-- BOBU X OAuth Reverification
-- Step 1: Registry only
-- Does not reset verification or modify GP.


CREATE TABLE public.builder_x_oauth_resets (
  builder_id uuid PRIMARY KEY
    REFERENCES public.builder_profiles(builder_id)
    ON DELETE RESTRICT,

  reset_at timestamptz NOT NULL DEFAULT now(),

  old_auth_identity_id uuid NOT NULL UNIQUE,

  old_provider_user_id text NOT NULL UNIQUE CHECK (btrim(old_provider_user_id) <> ''),

  previously_rewarded boolean NOT NULL,

  reward_idempotency_key text NOT NULL UNIQUE,

  status text NOT NULL DEFAULT 'pending'
    CHECK (
      status IN (
        'pending',
        'relinked',
        'rewarded'
      )
    ),

  reversed_at timestamptz,

  relinked_at timestamptz,

  rewarded_at timestamptz,

  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT x_oauth_reset_reversal_state_check
    CHECK (
      (previously_rewarded = true AND reversed_at IS NOT NULL AND reversed_at = reset_at)
      OR
      (previously_rewarded = false AND reversed_at IS NULL)
    ),

  CONSTRAINT x_oauth_reset_reward_state_check
    CHECK (
      (status = 'pending' AND relinked_at IS NULL AND rewarded_at IS NULL)
      OR (status = 'relinked' AND relinked_at IS NOT NULL AND relinked_at >= reset_at AND rewarded_at IS NULL)
      OR (status = 'rewarded' AND relinked_at IS NOT NULL AND relinked_at >= reset_at AND rewarded_at IS NOT NULL AND rewarded_at >= relinked_at)
    )
);

CREATE INDEX IF NOT EXISTS
  idx_builder_x_oauth_resets_status
ON public.builder_x_oauth_resets(status);

ALTER TABLE public.builder_x_oauth_resets
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE
  public.builder_x_oauth_resets
FROM PUBLIC, anon, authenticated;

GRANT SELECT
ON TABLE public.builder_x_oauth_resets
TO service_role;

COMMENT ON TABLE public.builder_x_oauth_resets IS
  'Server-managed X OAuth reset registry. '
  'A new linked X identity must be verified '
  'before a replacement Genesis reward is granted.';



-- Source: 02_protect_reset_registry.sql
-- BOBU X OAuth reset registry protection
-- Run only after 01_create_reset_registry.sql.
-- No GP or social verification changes.


CREATE OR REPLACE FUNCTION public.protect_x_oauth_reset_registry()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'X OAuth reset records cannot be deleted';
  END IF;

  IF NEW.builder_id IS DISTINCT FROM OLD.builder_id
     OR NEW.reset_at IS DISTINCT FROM OLD.reset_at
     OR NEW.old_auth_identity_id IS DISTINCT FROM OLD.old_auth_identity_id
     OR NEW.old_provider_user_id IS DISTINCT FROM OLD.old_provider_user_id
     OR NEW.previously_rewarded IS DISTINCT FROM OLD.previously_rewarded
     OR NEW.reward_idempotency_key IS DISTINCT FROM OLD.reward_idempotency_key
     OR NEW.reversed_at IS DISTINCT FROM OLD.reversed_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (OLD.relinked_at IS NOT NULL AND NEW.relinked_at IS DISTINCT FROM OLD.relinked_at)
  THEN
    RAISE EXCEPTION 'X OAuth reset identity and reward key are immutable';
  END IF;

  IF OLD.status = 'rewarded' THEN
    RAISE EXCEPTION 'Completed X OAuth resets cannot be modified';
  END IF;

  IF OLD.status = 'pending'
     AND NEW.status NOT IN ('pending', 'relinked')
  THEN
    RAISE EXCEPTION 'Invalid X OAuth reset status transition';
  END IF;

  IF OLD.status = 'relinked'
     AND NEW.status NOT IN ('relinked', 'rewarded')
  THEN
    RAISE EXCEPTION 'Invalid X OAuth reset status transition';
  END IF;

  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION
  public.protect_x_oauth_reset_registry()
FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS
  trg_protect_x_oauth_reset_registry
ON public.builder_x_oauth_resets;

CREATE TRIGGER trg_protect_x_oauth_reset_registry
BEFORE UPDATE OR DELETE
ON public.builder_x_oauth_resets
FOR EACH ROW
EXECUTE FUNCTION public.protect_x_oauth_reset_registry();



-- Source: 03_verify_fresh_x_identity.sql
-- BOBU X OAuth Reverification
-- Fresh identity verification only.
-- Does not award GP or modify verification status.


CREATE OR REPLACE FUNCTION public.verify_fresh_x_oauth_identity(
  p_builder_id uuid,
  p_provider_user_id text
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_reset public.builder_x_oauth_resets%ROWTYPE;
  v_new_identity_id uuid;
BEGIN
  SELECT *
  INTO v_reset
  FROM public.builder_x_oauth_resets
  WHERE builder_id = p_builder_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF p_provider_user_id IS DISTINCT FROM v_reset.old_provider_user_id THEN
    RETURN false;
  END IF;

  IF v_reset.status = 'rewarded' THEN
    RETURN false;
  END IF;

  SELECT ai.id
  INTO v_new_identity_id
  FROM auth.identities ai
  WHERE ai.user_id = p_builder_id
    AND ai.provider = 'x'
    AND ai.id <> v_reset.old_auth_identity_id
    AND ai.created_at > v_reset.reset_at
    AND ai.provider_id = p_provider_user_id
    AND (ai.identity_data ->> 'sub' IS NULL
         OR ai.identity_data ->> 'sub' = p_provider_user_id)
  ORDER BY ai.created_at DESC
  LIMIT 1;

  RETURN v_new_identity_id IS NOT NULL;
END;
$$;

REVOKE ALL ON FUNCTION
  public.verify_fresh_x_oauth_identity(uuid, text)
FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION
  public.verify_fresh_x_oauth_identity(uuid, text)
TO service_role;



-- Source: 04_claim_x_reward_reset_aware.sql

create or replace function public.claim_x_identity_reward(
  p_builder_id uuid,
  p_provider_user_id text,
  p_username text default null
)
returns table (
  verified boolean,
  rewarded boolean,
  already_rewarded boolean,
  reward_gp bigint,
  total_gp bigint,
  ledger_id uuid,
  completed_at timestamptz,
  reason text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_provider_user_id text;
  v_username text;
  v_existing_builder_id uuid;
  v_rewarded boolean;
  v_total_gp bigint;
  v_ledger_id uuid;
  v_completed_at timestamptz;
  v_reward_gp constant bigint := 5000;
  v_reset public.builder_x_oauth_resets%rowtype;
  v_has_reset boolean := false;
  v_reward_key text;
begin
  if p_builder_id is null then
    raise exception 'Builder ID is required.';
  end if;

  v_provider_user_id :=
    trim(coalesce(p_provider_user_id, ''));

  v_username :=
    nullif(trim(coalesce(p_username, '')), '');

  if v_provider_user_id = '' then
    raise exception 'X provider user ID is required.';
  end if;

  -- Shared release lock: administrative reset takes the exclusive lock.
  perform pg_catalog.pg_advisory_xact_lock_shared(81420261103);
  v_completed_at := clock_timestamp();
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('x:' || v_provider_user_id, 0));
  perform 1 from public.builder_profiles where builder_id = p_builder_id for update;
  if not found then raise exception 'Builder profile not found'; end if;

  -- Every claim, including first-time users, requires authoritative Auth proof.
  perform 1 from auth.identities ai
  where ai.user_id = p_builder_id and ai.provider = 'x'
    and ai.provider_id = v_provider_user_id
    and (ai.identity_data ->> 'sub' is null or ai.identity_data ->> 'sub' = v_provider_user_id)
  for share;
  if not found then raise exception 'Trusted X OAuth identity required'; end if;

  -- Reserve original provider IDs permanently, even while an owner is unlinked.
  if exists (select 1 from public.builder_x_oauth_resets r
             where r.old_provider_user_id = v_provider_user_id and r.builder_id <> p_builder_id) then
    raise exception 'X identity is reserved to its original Builder';
  end if;

  /*
   * Reset users must prove a newly linked X OAuth identity.
   * This check runs before changing verification or awarding GP.
   */
  select *
  into v_reset
  from public.builder_x_oauth_resets
  where builder_id = p_builder_id
  for update;

  v_has_reset := found;

  if v_has_reset then
    if v_provider_user_id is distinct from v_reset.old_provider_user_id then
      raise exception 'Original X account required';
    end if;
    if v_reset.previously_rewarded then
      if v_reset.reversed_at is null then
        raise exception
          'X OAuth reward reversal must be completed before re-verification';
      end if;

      if not exists (
        select 1
        from public.builder_reward_ledger as ledger
        where ledger.builder_id = p_builder_id
          and ledger.provider = 'x'
          and ledger.entry_type = 'debit'
          and ledger.reward_type = 'reward_reversal'
          and ledger.amount = v_reward_gp
          and ledger.idempotency_key = concat(
            'social-verification:x:reversal:',
            p_builder_id::text
          )
      ) then
        raise exception 'Verified X GP reversal ledger entry is required';
      end if;
    else
      if v_reset.reversed_at is not null then
        raise exception 'Unexpected reversal for unrewarded X identity';
      end if;

      if exists (
        select 1
        from public.builder_reward_ledger as ledger
        where ledger.builder_id = p_builder_id
          and ledger.provider = 'x'
          and ledger.entry_type = 'debit'
          and ledger.idempotency_key = concat(
            'social-verification:x:reversal:',
            p_builder_id::text
          )
      ) then
        raise exception 'Unexpected X reversal ledger entry';
      end if;
    end if;

    if v_reset.status = 'rewarded' then
      if not exists (select 1 from public.builder_reward_ledger l
        where l.builder_id = p_builder_id and l.idempotency_key = v_reset.reward_idempotency_key
          and l.provider = 'x' and l.reward_type = 'social_verification'
          and l.entry_type = 'credit' and l.amount = v_reward_gp) then
        raise exception 'Completed X reset is missing its replacement ledger credit';
      end if;
      return query
      select
        true,
        false,
        true,
        0::bigint,
        coalesce(profile.gp, 0),
        null::uuid,
        v_reset.rewarded_at,
        'already_rewarded'::text
      from public.builder_profiles as profile
      where profile.builder_id = p_builder_id;

      return;
    end if;

    if not public.verify_fresh_x_oauth_identity(
      p_builder_id,
      v_provider_user_id
    ) then
      return query
      select
        false,
        false,
        false,
        0::bigint,
        coalesce(profile.gp, 0),
        null::uuid,
        null::timestamptz,
        'fresh_x_oauth_required'::text
      from public.builder_profiles as profile
      where profile.builder_id = p_builder_id;

      return;
    end if;

    v_reward_key := v_reset.reward_idempotency_key;
  else
    v_reward_key := concat(
      'social-verification:x:',
      p_builder_id::text
    );
  end if;

  if exists (select 1 from public.builder_social_identities s
             where s.builder_id = p_builder_id and lower(s.provider) = 'x'
               and s.provider_user_id is distinct from v_provider_user_id) then
    raise exception 'Original X account required';
  end if;

  /*
   * One X identity may belong to only one Builder.
   */
  select identity.builder_id
  into v_existing_builder_id
  from public.builder_social_identities as identity
  where lower(identity.provider) = 'x'
    and identity.provider_user_id = v_provider_user_id
  limit 1
  for update;

  if (
    v_existing_builder_id is not null
    and v_existing_builder_id <> p_builder_id
  ) then
    return query
    select
      false,
      false,
      false,
      0::bigint,
      coalesce(profile.gp, 0),
      null::uuid,
      null::timestamptz,
      'identity_already_linked'::text
    from public.builder_profiles as profile
    where profile.builder_id = p_builder_id;

    if not found then
      return query
      select
        false,
        false,
        false,
        0::bigint,
        0::bigint,
        null::uuid,
        null::timestamptz,
        'identity_already_linked'::text;
    end if;

    return;
  end if;

  /*
   * Create or refresh the trusted X identity first.
   * The whole function remains one PostgreSQL transaction.
   */
  insert into public.builder_social_identities (
    builder_id,
    provider,
    provider_user_id,
    username,
    verified,
    verified_at,
    updated_at
  )
  values (
    p_builder_id,
    'x',
    v_provider_user_id,
    v_username,
    true,
    v_completed_at,
    v_completed_at
  )
  on conflict on constraint
    builder_social_identities_builder_id_provider_key
  do update
  set
    provider_user_id = excluded.provider_user_id,
    username = excluded.username,
    verified = true,
    verified_at = coalesce(
      public.builder_social_identities.verified_at,
      excluded.verified_at
    ),
    updated_at = excluded.updated_at;

  select
    reward.awarded,
    reward.total_gp,
    reward.ledger_id
  into
    v_rewarded,
    v_total_gp,
    v_ledger_id
  from public.award_builder_gp(
    p_builder_id,
    'social_verification',
    v_reward_gp,
    v_reward_key,
    'x',
    jsonb_build_object(
      'provider_user_id',
      v_provider_user_id,
      'username',
      v_username
    )
  ) as reward;

  -- An idempotency conflict must resolve to the exact intended credit.
  if not exists (select 1 from public.builder_reward_ledger l
    where l.builder_id = p_builder_id and l.idempotency_key = v_reward_key
      and l.provider = 'x' and l.reward_type = 'social_verification'
      and l.entry_type = 'credit' and l.amount = v_reward_gp) then
    raise exception 'X reward ledger credit mismatch';
  end if;

  update public.builder_social_identities
  set
    verified = true,
    verified_at = coalesce(
      verified_at,
      v_completed_at
    ),
    reward_claimed = true,
    reward_claimed_at = coalesce(
      reward_claimed_at,
      v_completed_at
    ),
    updated_at = v_completed_at
  where builder_id = p_builder_id
    and lower(provider) = 'x';

  /*
   * Complete the reset cycle in the same transaction
   * as the GP ledger credit and identity update.
   */
  if v_has_reset then
    -- Fresh X Auth identity has already been verified.
    -- Follow the registry's permitted state transitions.
    update public.builder_x_oauth_resets
    set
      status = 'relinked',
      relinked_at = coalesce(relinked_at, v_completed_at)
    where builder_id = p_builder_id
      and status = 'pending';

    update public.builder_x_oauth_resets
    set
      status = 'rewarded',
      relinked_at = coalesce(relinked_at, v_completed_at),
      rewarded_at = v_completed_at
    where builder_id = p_builder_id
      and status in ('pending', 'relinked')
      and (
        v_rewarded
        or exists (
          select 1
          from public.builder_reward_ledger as ledger
          where ledger.builder_id = p_builder_id
            and ledger.idempotency_key = v_reward_key
            and ledger.entry_type = 'credit'
            and ledger.amount = v_reward_gp
        )
      );

    if not found then
      raise exception
        'X OAuth reset reward could not be finalized';
    end if;
  end if;

  return query
  select
    true,
    v_rewarded,
    not v_rewarded,
    case
      when v_rewarded then v_reward_gp
      else 0::bigint
    end,
    coalesce(v_total_gp, 0),
    v_ledger_id,
    v_completed_at,
    case
      when v_rewarded then 'rewarded'
      else 'already_rewarded'
    end;
end;
$$;


revoke all
on function public.claim_x_identity_reward(
  uuid,
  text,
  text
)
from public, anon, authenticated;

grant execute
on function public.claim_x_identity_reward(
  uuid,
  text,
  text
)
to service_role;


comment on function public.claim_x_identity_reward(
  uuid,
  text,
  text
) is
  'Atomically links and verifies a trusted Supabase X OAuth identity, prevents cross-Builder identity reuse and credits the one-time 5000 GP reward.';



-- Source: 08_atomic_population_reset.sql
-- Installs an administrator-only operation. DOES NOT execute it.

CREATE OR REPLACE FUNCTION public.reset_x_oauth_population(p_project_ref text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_reset_at timestamptz;
BEGIN
  IF p_project_ref IS DISTINCT FROM 'pvemtnmeewyaqgindocs' THEN
    RAISE EXCEPTION 'Production project acknowledgement required';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(81420261103);
  -- Freeze the population, balances and ledger through validation and mutation.
  LOCK TABLE auth.identities IN SHARE MODE;
  LOCK TABLE public.builder_profiles, public.builder_social_identities,
    public.builder_reward_ledger, public.builder_x_oauth_resets IN EXCLUSIVE MODE;
  v_reset_at := clock_timestamp();
  IF EXISTS (SELECT 1 FROM public.builder_x_oauth_resets) THEN
    RAISE EXCEPTION 'Reset registry must be empty; repeated execution refused';
  END IF;
  CREATE TEMP TABLE x_reset_population ON COMMIT DROP AS
  SELECT ai.user_id AS builder_id, ai.id AS identity_id, ai.provider_id,
    s.provider_user_id AS social_provider_id, s.reward_claimed,
    p.personal_gp, p.gp, p.eligible_network_gp,
    p.pending_network_gp,
    (SELECT count(*) FROM public.builder_reward_ledger l
      WHERE l.builder_id = ai.user_id AND ((lower(l.provider) = 'x' AND l.reward_type IN ('social_verification', 'reward_reversal'))
          OR lower(l.idempotency_key) LIKE 'social-verification:x:%')) AS oauth_record_count,
    (SELECT count(*) FROM public.builder_reward_ledger l
      WHERE l.builder_id = ai.user_id AND l.provider = 'x'
      AND l.entry_type = 'credit' AND l.reward_type = 'social_verification'
      AND l.amount = 5000
      AND l.idempotency_key = 'social-verification:x:' || ai.user_id::text) AS credit_count
  FROM auth.identities ai
  LEFT JOIN public.builder_profiles p ON p.builder_id = ai.user_id
  LEFT JOIN public.builder_social_identities s ON s.builder_id = ai.user_id AND lower(s.provider) = 'x'
  WHERE ai.provider = 'x';

  IF (SELECT count(*) FROM x_reset_population) <> 60
     OR (SELECT count(DISTINCT builder_id) FROM x_reset_population) <> 60
     OR (SELECT count(DISTINCT provider_id) FROM x_reset_population) <> 60
     OR (SELECT count(*) FROM x_reset_population WHERE credit_count = 1) <> 55
     OR (SELECT count(*) FROM x_reset_population WHERE credit_count = 0) <> 5
     OR (SELECT sum(credit_count * 5000) FROM x_reset_population) <> 275000 THEN
    RAISE EXCEPTION 'STOP: expected 60 connected / 55 rewarded / 5 unrewarded / 275000 GP';
  END IF;
  IF EXISTS (SELECT 1 FROM x_reset_population WHERE
       personal_gp IS NULL OR gp IS NULL OR eligible_network_gp IS NULL
       OR personal_gp < 0 OR gp <> personal_gp + eligible_network_gp
       OR provider_id IS NULL OR btrim(provider_id) = ''
       OR (social_provider_id IS NOT NULL AND social_provider_id <> provider_id)
       OR oauth_record_count <> credit_count OR credit_count NOT IN (0,1)
       OR (credit_count = 1 AND (personal_gp < 5000 OR reward_claimed IS DISTINCT FROM true))
       OR (credit_count = 0 AND reward_claimed IS TRUE)) THEN
    RAISE EXCEPTION 'STOP: identity, historical reward or balance validation failed';
  END IF;
  -- Validate the OAuth namespace globally, including users outside the population.
  -- Unrelated X campaign credits are neither OAuth evidence nor reversal targets.
  -- Ambiguous generic X reward_reversal rows still require manual review.
  IF (SELECT count(*) FROM public.builder_reward_ledger l WHERE ((lower(l.provider) = 'x' AND l.reward_type IN ('social_verification', 'reward_reversal'))
          OR lower(l.idempotency_key) LIKE 'social-verification:x:%')) <> 55
     OR EXISTS (SELECT 1 FROM public.builder_reward_ledger l
       WHERE ((lower(l.provider) = 'x' AND l.reward_type IN ('social_verification', 'reward_reversal'))
          OR lower(l.idempotency_key) LIKE 'social-verification:x:%')
         AND (l.provider = 'x' AND l.reward_type = 'social_verification'
          AND l.entry_type = 'credit' AND l.amount = 5000
          AND l.idempotency_key = 'social-verification:x:' || l.builder_id::text) IS NOT TRUE) THEN
    RAISE EXCEPTION 'STOP: duplicate, malformed, reversed or inconsistent X OAuth ledger history';
  END IF;
  IF EXISTS (SELECT 1 FROM auth.identities ai JOIN x_reset_population p ON ai.id = p.identity_id
    WHERE ai.identity_data ->> 'sub' IS NOT NULL AND ai.identity_data ->> 'sub' <> p.provider_id) THEN
    RAISE EXCEPTION 'STOP: Auth provider binding mismatch';
  END IF;

  INSERT INTO public.builder_x_oauth_resets
    (builder_id, reset_at, old_auth_identity_id, old_provider_user_id,
     previously_rewarded, reward_idempotency_key, reversed_at)
  SELECT builder_id, v_reset_at, identity_id, provider_id, credit_count = 1,
    'social-verification:x:reset-v2:' || builder_id::text,
    CASE WHEN credit_count = 1 THEN v_reset_at END
  FROM x_reset_population;

  INSERT INTO public.builder_reward_ledger
    (builder_id, reward_type, provider, amount, entry_type, idempotency_key, metadata)
  SELECT builder_id, 'reward_reversal', 'x', 5000, 'debit',
    'social-verification:x:reversal:' || builder_id::text,
    jsonb_build_object('reason', 'x_oauth_reverification', 'reset_at', v_reset_at)
  FROM x_reset_population WHERE credit_count = 1;

  UPDATE public.builder_profiles p SET personal_gp = p.personal_gp - 5000,
    gp = p.gp - 5000
  FROM x_reset_population b WHERE p.builder_id = b.builder_id AND b.credit_count = 1;

  UPDATE public.builder_social_identities s SET verified = false, verified_at = NULL,
    reward_claimed = false, reward_claimed_at = NULL, updated_at = v_reset_at
  FROM x_reset_population b WHERE s.builder_id = b.builder_id AND lower(s.provider) = 'x';

  IF EXISTS (SELECT 1 FROM x_reset_population b JOIN public.builder_profiles p USING (builder_id)
    WHERE p.personal_gp IS DISTINCT FROM b.personal_gp - b.credit_count * 5000
       OR p.gp IS DISTINCT FROM b.gp - b.credit_count * 5000
       OR p.eligible_network_gp IS DISTINCT FROM b.eligible_network_gp
       OR p.pending_network_gp IS DISTINCT FROM b.pending_network_gp)
    OR (SELECT count(*) FROM public.builder_x_oauth_resets) <> 60
    OR (SELECT count(*) FROM public.builder_reward_ledger l
      JOIN public.builder_x_oauth_resets r ON r.builder_id = l.builder_id
      WHERE l.provider = 'x' AND l.entry_type = 'debit' AND l.reward_type = 'reward_reversal'
        AND l.idempotency_key = 'social-verification:x:reversal:' || r.builder_id::text) <> 55
    OR (SELECT sum(amount) FROM public.builder_reward_ledger l
      JOIN public.builder_x_oauth_resets r ON r.builder_id = l.builder_id
      WHERE l.provider = 'x' AND l.entry_type = 'debit' AND l.reward_type = 'reward_reversal'
        AND l.idempotency_key = 'social-verification:x:reversal:' || r.builder_id::text) <> 275000 THEN
    RAISE EXCEPTION 'STOP: reset postconditions failed';
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.reset_x_oauth_population(text) FROM PUBLIC, anon, authenticated, service_role;

COMMIT;
